<?php
namespace App\Modules\Orders\Domain\Models;
use App\Modules\Catalog\Domain\Models\ProductPresentation;use App\Modules\Identity\Domain\Models\AuthorizationRequest;use App\Modules\Pricing\Domain\Models\PriceListItem;use Illuminate\Database\Eloquent\Attributes\Fillable;use Illuminate\Database\Eloquent\Concerns\HasUlids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;
#[Fillable(['sales_order_id','presentation_id','price_list_item_id','ordered_quantity','reserved_quantity','produced_quantity','delivered_quantity','list_unit_price','unit_price','discount','line_total','price_reason','price_authorization_id','notes'])]
class SalesOrderLine extends Model {use HasUlids;public function order():BelongsTo{return $this->belongsTo(SalesOrder::class,'sales_order_id');}public function presentation():BelongsTo{return $this->belongsTo(ProductPresentation::class);}public function priceListItem():BelongsTo{return $this->belongsTo(PriceListItem::class);}public function priceAuthorization():BelongsTo{return $this->belongsTo(AuthorizationRequest::class);}public function reservations():HasMany{return $this->hasMany(InventoryReservation::class);}protected function casts():array{return ['ordered_quantity'=>'decimal:6','reserved_quantity'=>'decimal:6','produced_quantity'=>'decimal:6','delivered_quantity'=>'decimal:6','list_unit_price'=>'integer','unit_price'=>'integer','discount'=>'integer','line_total'=>'integer'];}}
